<script>document.addEventListener('DOMContentLoaded',function(){const input=document.getElementById('channelSearch');if(!input)return;const cards=Array.from(document.querySelectorAll('#channelGrid .oh-channel'));const empty=document.getElementById('channelNoResults');input.addEventListener('input',function(){const query=this.value.trim().toLocaleLowerCase();let visible=0;cards.forEach(function(card){const matches=!query||card.dataset.channelName.includes(query);card.classList.toggle('is-hidden',!matches);if(matches)visible++});empty.classList.toggle('is-visible',visible===0)})});</script>
